class Solution {
    public int maxProfit(int k, int[] prices) {
        int n = prices.length;
        if (k == 0 || n < 2) return 0;
        if (k >= n / 2) {
            int profit = 0;
            for (int i = 1; i < n; i++) profit += Math.max(0, prices[i] - prices[i - 1]);
            return profit;
        }
        int[] buy = new int[k];
        int[] sell = new int[k];
        java.util.Arrays.fill(buy, Integer.MIN_VALUE / 4);
        for (int price : prices) {
            for (int i = 0; i < k; i++) {
                buy[i] = Math.max(buy[i], (i == 0 ? 0 : sell[i - 1]) - price);
                sell[i] = Math.max(sell[i], buy[i] + price);
            }
        }
        return sell[k - 1];
    }
}

class Solution {
    public int maxProfit(int k, int[] prices) {
        int n = prices.length;
        if (k == 0 || n < 2) return 0;
        if (k >= n / 2) {
            int profit = 0;
            for (int i = 1; i < n; i++) {
                if (prices[i] > prices[i - 1]) profit += prices[i] - prices[i - 1];
            }
            return profit;
        }
        int[][] dp = new int[k + 1][n];
        for (int t = 1; t <= k; t++) {
            int maxDiff = -prices[0];
            for (int i = 1; i < n; i++) {
                dp[t][i] = Math.max(dp[t][i - 1], prices[i] + maxDiff);
                maxDiff = Math.max(maxDiff, dp[t - 1][i] - prices[i]);
            }
        }
        return dp[k][n - 1];
    }
}

class Solution {
    public int maxProfit(int k, int[] prices) {
        if (k == 0 || prices.length < 2) return 0;
        Integer[][][] memo = new Integer[prices.length][k + 1][2];
        return dfs(0, k, 0, prices, memo);
    }

    private int dfs(int day, int remaining, int holding, int[] prices, Integer[][][] memo) {
        if (day == prices.length) return 0;
        if (memo[day][remaining][holding] != null) return memo[day][remaining][holding];
        int best = dfs(day + 1, remaining, holding, prices, memo);
        if (holding == 1) {
            if (remaining > 0) {
                best = Math.max(best, prices[day] + dfs(day + 1, remaining - 1, 0, prices, memo));
            }
        } else if (remaining > 0) {
            best = Math.max(best, -prices[day] + dfs(day + 1, remaining, 1, prices, memo));
        }
        memo[day][remaining][holding] = best;
        return best;
    }
}

class Solution {
    public int maxProfit(int k, int[] prices) {
        int n = prices.length;
        if (k == 0 || n < 2) return 0;
        if (k >= n / 2) {
            int profit = 0;
            for (int day = 1; day < n; day++) profit += Math.max(0, prices[day] - prices[day - 1]);
            return profit;
        }
        int[] local = new int[k + 1];
        int[] global = new int[k + 1];
        for (int day = 1; day < n; day++) {
            int diff = prices[day] - prices[day - 1];
            for (int t = k; t >= 1; t--) {
                local[t] = Math.max(global[t - 1] + Math.max(diff, 0), local[t] + diff);
                global[t] = Math.max(global[t], local[t]);
            }
        }
        return global[k];
    }
}
